import { useEffect, useRef, useState, type ReactNode } from "react"
import { AccountProfile, csrfHeaders } from "../lib/accountProfile"
import { getInitialLocale } from "../lib/i18n"
import { StoreProvider } from "../lib/store"

interface Session {
  authenticated: boolean
  account?: { id: string }
  expiresAt?: string
}

export default function AccountGate({ children }: { children: ReactNode }) {
  const [session, setSession] = useState<Session | null>(null)
  const [error, setError] = useState(false)
  const [client, setClient] = useState<AccountProfile | null>(null)
  const [checking, setChecking] = useState(true)
  const [logoutIntent, setLogoutIntent] = useState(false)
  const clients = useRef(new Map<string, AccountProfile>())
  const current = useRef<AccountProfile | null>(null)
  const epoch = useRef(0)
  const pt = getInitialLocale() === "pt-BR"
  const probe = async () => {
    const ticket = ++epoch.current
    // Hide while checking, retaining same-account unsaved work. Dispose before
    // displaying another account; never attach A's client or queue to B.
    setChecking(true)
    try {
      const response = await fetch("/api/auth/session", {
        credentials: "same-origin",
        cache: "no-store",
        signal: AbortSignal.timeout(10_000),
      })
      if (!response.ok) throw new Error()
      const value: Session = await response.json()
      if (ticket !== epoch.current) return
      if (
        typeof value.authenticated !== "boolean" ||
        (value.authenticated &&
          (!value.account?.id ||
            !value.expiresAt ||
            !Number.isFinite(Date.parse(value.expiresAt))))
      )
        throw new Error()
      setSession(value)
      setError(false)
      const accountId = value.authenticated ? value.account!.id : null
      if (current.current?.accountId !== accountId) {
        current.current?.dispose()
        current.current = null
        setClient(null)
        setLogoutIntent(false)
      }
      if (accountId && !current.current) {
        const next =
          clients.current.get(accountId) ?? new AccountProfile(accountId)
        clients.current.set(accountId, next)
        next.resume()
        current.current = next
        setClient(next)
      }
      setChecking(false)
    } catch {
      if (ticket === epoch.current) {
        setError(true)
        setChecking(true)
      }
    }
  }
  useEffect(() => {
    void probe()
    const focus = () => void probe()
    const visible = () => {
      if (document.visibilityState === "visible") void probe()
    }
    window.addEventListener("focus", focus)
    document.addEventListener("visibilitychange", visible)
    return () => {
      epoch.current++
      for (const retained of clients.current.values()) retained.dispose()
      window.removeEventListener("focus", focus)
      document.removeEventListener("visibilitychange", visible)
    }
  }, [])
  useEffect(() => {
    if (!session?.authenticated || !session.expiresAt) return
    const timer = setTimeout(
      () => void probe(),
      Math.min(
        2_147_483_647,
        Math.max(0, Date.parse(session.expiresAt) - Date.now()),
      ),
    )
    return () => clearTimeout(timer)
  }, [session?.authenticated, session?.expiresAt])
  const logout = async (discard = false) => {
    if (discard) {
      try {
        current.current?.discardRecovery()
      } catch {
        setError(true)
        return
      }
    }
    setLogoutIntent(false)
    ++epoch.current
    current.current?.dispose()
    current.current = null
    setClient(null)
    setSession(null)
    try {
      const response = await fetch("/api/auth/logout", {
        method: "POST",
        credentials: "same-origin",
        headers: csrfHeaders(),
      })
      if (!response.ok) throw new Error()
      await probe()
    } catch {
      setError(true)
    }
  }
  const pendingInTab = [...clients.current.values()].some((retained) =>
    retained.hasRecovery(),
  )
  const downloadPending = () => {
    if (!client) return
    const url = URL.createObjectURL(
      new Blob([JSON.stringify(client.recoveryExport(), null, 2)], {
        type: "application/json",
      }),
    )
    const anchor = document.createElement("a")
    anchor.href = url
    anchor.download = "careeros-pending-save-recovery.json"
    anchor.click()
    setTimeout(() => URL.revokeObjectURL(url), 1000)
  }
  if (!client)
    return (
      <main className="mx-auto max-w-xl space-y-4 p-8">
        <h1 className="text-2xl font-semibold">CareerOS</h1>
        {error ? (
          <>
            <p role="alert">
              {pt
                ? "Não foi possível verificar sua sessão. Tente novamente."
                : "Your session could not be checked. Try again."}
            </p>
            <button onClick={() => void probe()}>
              {pt ? "Tentar novamente" : "Try again"}
            </button>
          </>
        ) : session?.authenticated === false ? (
          <>
            <p>
              {pt
                ? "Entre para criar e salvar seu Perfil na sua conta."
                : "Sign in to create and save your account Profile."}
            </p>
            <a
              className="inline-block rounded bg-indigo-700 px-4 py-2 text-white"
              href="/api/auth/google/start"
              target={pendingInTab ? "_blank" : undefined}
              rel={pendingInTab ? "noopener" : undefined}
            >
              {pt ? "Entrar com Google" : "Sign in with Google"}
            </a>
            {pendingInTab && (
              <p>
                {pt
                  ? "O trabalho pendente continua nesta aba. Entre na outra aba e volte aqui para recuperar somente o trabalho da mesma conta."
                  : "Pending work remains in this tab. Sign in in the other tab, then return here to recover work for that same account."}
              </p>
            )}
          </>
        ) : (
          <p role="status">
            {pt ? "Verificando sessão…" : "Checking session…"}
          </p>
        )}
      </main>
    )
  return (
    <>
      {checking && (
        <div role={error ? "alert" : "status"} className="p-4">
          {error ? (
            <button onClick={() => void probe()}>
              {pt
                ? "Verificação indisponível. Tentar novamente"
                : "Session check unavailable. Try again"}
            </button>
          ) : pt ? (
            "Verificando sessão…"
          ) : (
            "Checking session…"
          )}
        </div>
      )}
      <div hidden={checking}>
        <StoreProvider key={client.accountId} account={client}>
          <div className="flex items-center justify-between border-b px-4 py-2 text-sm">
            <span>
              {pt
                ? "Perfil da conta · salvar explicitamente"
                : "Account Profile · explicit Save"}
            </span>
            <button
              data-sign-out
              onClick={() =>
                client.hasRecovery() ? setLogoutIntent(true) : void logout()
              }
            >
              {pt ? "Sair" : "Sign out"}
            </button>
          </div>
          {logoutIntent && (
            <div
              role="dialog"
              aria-label={
                pt
                  ? "Salvar recuperação antes de sair"
                  : "Keep recovery before signing out"
              }
              data-pending-logout
              className="border-b p-4"
            >
              {error && (
                <p role="alert">
                  {pt
                    ? "Não foi possível descartar a recuperação. Baixe uma cópia e tente novamente."
                    : "Recovery could not be discarded. Download a copy and try again."}
                </p>
              )}
              <p>
                {pt
                  ? "Um salvamento ainda não foi confirmado. Manter ou descartar a cópia de recuperação? Descartar não desfaz um salvamento no servidor."
                  : "A Save is not confirmed. Keep or discard its recovery copy? Discarding does not undo a server Save."}
              </p>
              <div className="flex flex-wrap gap-4 py-2">
                <button data-logout-download onClick={downloadPending}>
                  {pt
                    ? "Baixar cópia de recuperação"
                    : "Download recovery copy"}
                </button>
                <button data-logout-keep onClick={() => void logout()}>
                  {pt
                    ? "Sair e manter recuperação nesta aba"
                    : "Sign out and keep recovery in this tab"}
                </button>
                <button data-logout-discard onClick={() => void logout(true)}>
                  {pt
                    ? "Descartar recuperação e sair"
                    : "Discard recovery and sign out"}
                </button>
                <button
                  data-logout-cancel
                  onClick={() => setLogoutIntent(false)}
                >
                  {pt ? "Cancelar" : "Cancel"}
                </button>
              </div>
            </div>
          )}
          {children}
        </StoreProvider>
      </div>
    </>
  )
}

import type { Page } from "../lib/types"
import { hasQualificationEvidence } from "../lib/qualificationEvidence"
import { useI18n, useStore } from "../lib/store"

export default function JourneyGuidance({
  page,
  setPage,
}: {
  page: Page
  setPage: (page: Page) => void
}) {
  const { state, profileDocument, profileSaving, accountId } = useStore()
  const { t } = useI18n()
  const profileReady =
    !state.profileError &&
    !profileSaving &&
    hasQualificationEvidence(profileDocument)
  const needsProfile = page === "home" && !profileReady

  return (
    <section
      aria-label={t("journey.context")}
      className="journey-guidance mx-auto max-w-6xl px-4 pt-6 sm:px-6"
    >
      <div
        className="flex flex-wrap items-start justify-between gap-3 border-b pb-4 text-sm"
        style={{ borderColor: "var(--color-border)" }}
      >
        <div className="min-w-0 max-w-2xl">
          <p className="font-semibold">
            {t(accountId ? "journey.accountMode" : "journey.localMode")}
          </p>
          <p className="mt-1" style={{ color: "var(--color-muted-fg)" }}>
            {page === "repository"
              ? t(accountId ? "journey.accountProfile" : "journey.profile")
              : page === "cv"
                ? t("journey.cv")
                : page === "results"
                  ? t("journey.results")
                  : t("journey.apply")}
          </p>
          {(page === "repository" || needsProfile) && (
            <p className="mt-2" role="status" aria-atomic="true">
              {state.profileError
                ? t("journey.profileUnavailable")
                : profileSaving
                  ? t("journey.profileSaving")
                  : profileReady
                    ? t("journey.profileReady")
                    : t("journey.profileNeeded")}
            </p>
          )}
        </div>
        {(needsProfile || (page === "repository" && profileReady)) && (
          <button
            type="button"
            className="border px-4 py-2 font-semibold"
            style={{ borderColor: "var(--color-fg)" }}
            onClick={() => setPage(needsProfile ? "repository" : "home")}
          >
            {t(needsProfile ? "journey.openProfile" : "journey.continueApply")}
          </button>
        )}
      </div>
    </section>
  )
}

// Browser-only synthetic transport for the actual AccountGate + StoreProvider.
// PostgreSQL behavior is independently exercised by Go integration tests.
import { useState } from "react"
import { createRoot } from "react-dom/client"
import AccountGate from "../src/components/AccountGate"
import { useStore } from "../src/lib/store"
import type { ProfileDocument } from "../src/lib/profileDocument"
import "../src/index.css"

type Scenario = {
  account: string
  expires: string
  fail: boolean
  loseAck: boolean
  defer: string
  release: (() => void) | null
  reads: string[]
  puts: string[]
  logoutCalls: number
  autoExpire: boolean
  documents: Record<string, ProfileDocument>
  operations: Record<string, unknown>
}
const scenario: Scenario = {
  account: "a",
  expires: new Date(Date.now() + 3600_000).toISOString(),
  fail: false,
  loseAck: false,
  defer: "",
  release: null,
  reads: [],
  puts: [],
  logoutCalls: 0,
  autoExpire: false,
  documents: {},
  operations: {},
  ...(window as Window & { accountServerFixture?: Partial<Scenario> })
    .accountServerFixture,
}
Object.assign(window, { accountScenario: scenario })
const get = Storage.prototype.getItem
Storage.prototype.getItem = function (key) {
  if (key === "careeros_repo" || key === "careeros_profile_v2")
    scenario.reads.push(key)
  return get.call(this, key)
}
const response = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status })
window.fetch = async (input, init = {}) => {
  const path = String(input)
  const owner = scenario.account
  if (path === "/api/auth/session") {
    const authenticated =
      !!owner &&
      !(scenario.autoExpire && Date.now() >= Date.parse(scenario.expires))
    return response({
      authenticated,
      account: authenticated ? { id: owner } : undefined,
      expiresAt: scenario.expires,
    })
  }
  if (path === "/api/auth/logout") {
    scenario.logoutCalls++
    scenario.account = ""
    return new Response(null, { status: 204 })
  }
  const headers = new Headers(init.headers)
  if (headers.get("X-CareerOS-Account") !== owner)
    return response({ error: "account_changed" }, 409)
  if (init.method === "PUT") {
    scenario.puts.push(String(init.body))
    if (scenario.fail) return response({ error: "storage_unavailable" }, 503)
    const command = JSON.parse(String(init.body))
    scenario.documents[owner] = command.document
    scenario.operations[owner + ":" + command.operationId] = {
      operationId: command.operationId,
      profileId: command.document.id,
      committedRevision: command.document.revision,
    }
    if (scenario.loseAck) {
      scenario.loseAck = false
      throw new Error("synthetic committed response loss")
    }
    return response({
      accountId: owner,
      document: scenario.documents[owner],
      outcome: scenario.operations[owner + ":" + command.operationId],
    })
  }
  if (scenario.fail) return response({ error: "storage_unavailable" }, 503)
  if (path.startsWith("/api/profile/operations/")) {
    const outcome = scenario.operations[owner + ":" + path.split("/").at(-1)]
    return outcome
      ? response({
          accountId: owner,
          document: scenario.documents[owner],
          outcome,
        })
      : response({ error: "not_found" }, 404)
  }
  const body = { accountId: owner, document: scenario.documents[owner] ?? null }
  if (scenario.defer === owner) {
    scenario.defer = ""
    await new Promise<void>((resolve) => {
      scenario.release = resolve
    })
  }
  return response(body)
}
function Workspace() {
  const {
    state,
    accountId,
    profileDocument,
    editCanonicalProfile,
    profileSaving,
  } = useStore()
  const [value, setValue] = useState("")
  return (
    <section data-workspace-account={accountId}>
      <p data-profile-name>{state.repository.fullName}</p>
      <input
        aria-label="Synthetic name"
        value={value}
        onChange={(e) => setValue(e.target.value)}
      />
      <button
        data-save
        disabled={profileSaving || !profileDocument}
        onClick={() =>
          profileDocument &&
          void editCanonicalProfile({
            type: "field",
            ownerId: profileDocument.id,
            field: "fullName",
            value,
          })
        }
      >
        Save
      </button>
    </section>
  )
}
createRoot(document.getElementById("root")!).render(
  <AccountGate>
    <Workspace />
  </AccountGate>,
)

import {
  emptyProfileView,
  migrateProfile,
  validateProfileDocument,
  type ProfileDocument,
} from "./profileDocument"
import { ProfileStorageError } from "./profileStorage"

export type SaveState = "idle" | "pending" | "failed" | "uncertain" | "confirmed"
interface SaveOutcome {
  operationId: string
  profileId: string
  committedRevision: number
}
export interface ProfileReply {
  accountId: string
  document: ProfileDocument | null
  outcome?: SaveOutcome
}
interface PendingSave {
  operationId: string
  expectedRevision: number
  document: ProfileDocument
}
type RecoveryStorage = Pick<Storage, "getItem" | "setItem" | "removeItem">
function tabRecoveryStorage(): RecoveryStorage | null {
  try {
    return typeof sessionStorage === "undefined" ? null : sessionStorage
  } catch {
    return null
  }
}

export function csrfHeaders(): Record<string, string> {
  const token = document.cookie
    .split(";")
    .map((v) => v.trim())
    .find((v) => v.startsWith("__Host-careeros_csrf="))
    ?.split("=")[1]
  return token ? { "X-CSRF-Token": decodeURIComponent(token) } : {}
}

// Account-scoped pending-work recovery only. The tab checkpoint contains no
// credentials and cannot supply account authority: open still requires a
// successful current server read before StoreProvider exposes any draft.
export class AccountProfile {
  active = true
  state: SaveState = "idle"
  historicalRevision: number | null = null
  private exists = false
  checkpointStored = false
  private lease = 0
  private pending: PendingSave | null = null
  private invalidCheckpoint: string | null = null
  private get recoveryKey() {
    return `careeros_pending_profile_v1:${this.accountId}`
  }
  constructor(
    readonly accountId: string,
    private notify: () => void = () => {},
    private request: typeof fetch = fetch,
    private storage: RecoveryStorage | null = tabRecoveryStorage(),
  ) {
    let raw: string | null = null
    try {
      raw = storage?.getItem(this.recoveryKey) ?? null
    } catch {
      /* Memory recovery remains available. */
    }
    if (raw !== null) {
      try {
        const saved = JSON.parse(raw)
        const p = saved.pendingSave
        if (
          saved.version !== 1 ||
          saved.accountId !== accountId ||
          !p ||
          typeof p.operationId !== "string" ||
          !/^[a-zA-Z0-9_-]{1,128}$/.test(p.operationId) ||
          !Number.isSafeInteger(p.expectedRevision) ||
          p.expectedRevision < 0 ||
          !validateProfileDocument(p.document) ||
          (p.expectedRevision > 0 &&
            p.document.revision !== p.expectedRevision + 1)
        )
          throw new Error()
        this.pending = p
        this.state = "uncertain"
        this.checkpointStored = true
      } catch {
        this.invalidCheckpoint = raw
        this.state = "failed"
      }
    }
  }
  dispose() {
    this.active = false
    this.lease++
    if (this.pending) this.state = "uncertain"
  }
  resume() {
    this.active = true
  }
  private assertActive(lease = this.lease) {
    if (!this.active || lease !== this.lease)
      throw new ProfileStorageError("account_changed")
  }
  private checkpoint() {
    try {
      this.storage?.setItem(
        this.recoveryKey,
        JSON.stringify(this.recoveryExport()),
      )
      this.checkpointStored = this.storage !== null
    } catch {
      this.checkpointStored = false
    }
  }
  private status(state: SaveState) {
    this.assertActive()
    this.state = state
    this.notify()
  }
  private async call(
    path: string,
    init: RequestInit = {},
  ): Promise<ProfileReply> {
    const lease = this.lease
    this.assertActive(lease)
    const response = await this.request(path, {
      ...init,
      credentials: "same-origin",
      cache: "no-store",
      headers: {
        "Content-Type": "application/json",
        "X-CareerOS-Account": this.accountId,
        ...csrfHeaders(),
        ...init.headers,
      },
      signal: AbortSignal.timeout(15_000),
    })
    this.assertActive(lease)
    const body = await response.json()
    this.assertActive(lease)
    if (!response.ok)
      throw new ProfileStorageError(
        response.status === 404
          ? "not_found"
          : response.status === 401
            ? "authentication"
            : body?.error === "account_changed"
              ? "account_changed"
              : response.status === 409
                ? "stale"
                : response.status === 422
                  ? "validation"
                  : "storage",
      )
    if (body.accountId !== this.accountId)
      throw new ProfileStorageError("account_changed")
    if (body.document !== null && !validateProfileDocument(body.document))
      throw new ProfileStorageError("validation")
    return body
  }
  async open(): Promise<ProfileDocument> {
    const lease = this.lease
    const reply = await this.call("/api/profile/current")
    this.assertActive(lease)
    this.exists = reply.document !== null
    return (
      reply.document ?? migrateProfile(emptyProfileView(), crypto.randomUUID())
    )
  }
  private confirm(reply: ProfileReply): ProfileDocument {
    const pending = this.pending
    if (
      !pending ||
      !reply.document ||
      reply.outcome?.operationId !== pending.operationId ||
      reply.outcome.profileId !== pending.document.id ||
      reply.outcome.committedRevision !== pending.document.revision ||
      reply.document.id !== pending.document.id ||
      reply.document.revision < pending.document.revision
    )
      throw new ProfileStorageError("validation")
    this.historicalRevision = reply.outcome.committedRevision
    this.exists = true
    this.pending = null
    try {
      this.storage?.removeItem(this.recoveryKey)
    } catch {
      this.checkpointStored = false
    }
    this.status("confirmed")
    // Return CURRENT authority, which may be newer than the historical outcome.
    return reply.document
  }
  async save(
    expected: ProfileDocument,
    candidate: ProfileDocument,
  ): Promise<ProfileDocument> {
    this.assertActive()
    if (
      !validateProfileDocument(candidate) ||
      candidate.id !== expected.id ||
      candidate.revision !== expected.revision + 1
    )
      throw new ProfileStorageError("validation")
    if (this.hasRecovery()) throw new ProfileStorageError("uncertain")
    this.pending = {
      operationId: crypto.randomUUID(),
      expectedRevision: this.exists ? expected.revision : 0,
      document: structuredClone(candidate),
    }
    this.checkpoint()
    return this.retry()
  }
  async retry(): Promise<ProfileDocument> {
    const lease = this.lease
    this.assertActive(lease)
    if (!this.pending) throw new ProfileStorageError("validation")
    this.status("pending")
    const confirm = (reply: ProfileReply) => {
      this.assertActive(lease)
      return this.confirm(reply)
    }
    try {
      return confirm(
        await this.call("/api/profile/current", {
          method: "PUT",
          body: JSON.stringify(this.pending),
        }),
      )
    } catch (error) {
      this.assertActive(lease)
      const definite =
        error instanceof ProfileStorageError &&
        ["validation", "stale", "account_changed", "authentication"].includes(
          error.code,
        )
      if (definite) {
        this.status("failed")
        throw error
      }
      // The response may be lost after commit. A read never repeats the write.
      try {
        return confirm(
          await this.call(
            `/api/profile/operations/${this.pending!.operationId}`,
          ),
        )
      } catch {
        this.assertActive(lease)
        this.status("uncertain")
        throw new ProfileStorageError("uncertain")
      }
    }
  }
  async refresh(): Promise<ProfileDocument> {
    const lease = this.lease
    if (this.pending) {
      const reply = await this.call(
        `/api/profile/operations/${this.pending.operationId}`,
      )
      this.assertActive(lease)
      return this.confirm(reply)
    }
    return this.open()
  }
  hasRecovery() {
    return this.pending !== null || this.invalidCheckpoint !== null
  }
  recoveryExport() {
    return {
      version: 1,
      accountId: this.accountId,
      pendingSave: this.recovery(),
      ...(this.invalidCheckpoint === null
        ? {}
        : { invalidCheckpoint: this.invalidCheckpoint }),
    }
  }
  discardRecovery() {
    // This discards a local recovery copy, never cancels/undoes a server commit.
    // Invalidate in-flight continuations before allowing another operation.
    try {
      this.storage?.removeItem(this.recoveryKey)
    } catch {
      throw new ProfileStorageError("storage")
    }
    this.lease++
    this.pending = null
    this.invalidCheckpoint = null
    this.state = "idle"
    this.notify()
  }
  recovery() {
    return this.pending ? structuredClone(this.pending) : null
  }
}

// Selected #258 D03/D04 cleanup is a domain deletion policy. It is applied
// before Save and independently enforced by Go; the byte store never rewrites.
export function applyAccountRetention(
  before: ProfileDocument,
  candidate: ProfileDocument,
): ProfileDocument {
  const next = structuredClone(candidate)
  const remaining = new Set(next.facts.map((f) => f.id))
  const removed = new Set(
    before.facts.filter((f) => !remaining.has(f.id)).map((f) => f.id),
  )
  const affected = new Set(
    before.links
      .filter((l) => l.kind === "supports" && removed.has(l.from.id))
      .map((l) => l.to.id),
  )
  const referenced = new Set(
    next.links
      .filter((l) => l.kind === "supports" && remaining.has(l.from.id))
      .map((l) => l.to.id),
  )
  next.evidence = next.evidence.filter(
    (e) => referenced.has(e.id) && !affected.has(e.id),
  )
  const kept = new Set(next.evidence.map((e) => e.id))
  for (const link of next.links)
    if (link.kind === "supports" && !kept.has(link.to.id)) {
      link.state = "invalidated"
      const fact = next.facts.find((f) => f.id === link.from.id)
      if (fact?.support === "supported") fact.support = "invalidated"
    }
  return next
}

import { applyIngestionDocument } from "./ingestionDocument"
import { AccountProfile, applyAccountRetention } from "./accountProfile"
import type { IngestionResult } from "./ingestion"
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useReducer,
  useRef,
  useState,
  ReactNode,
} from "react"
import { ProfessionalRepository, GeneratedMaterials } from "./types"
import {
  editProfile,
  type ProfileEdit,
  emptyProfileView,
  migrateProfile,
  profileView,
  type ProfileDocument,
} from "./profileDocument"
import {
  applySectionProposal,
  type SectionReviewRequest,
  type SectionProposal,
} from "./sectionReview"
import {
  openProfile,
  readProfile,
  browserProfileLock,
  saveProfile,
  PROFILE_KEY,
  LEGACY_KEY,
  ProfileStorageError,
  type ProfileStorageCode,
} from "./profileStorage"
import {
  getInitialLocale,
  isLocale,
  Locale,
  translate,
  TranslationKey,
  TranslationValue,
} from "./i18n"

interface AppState {
  uiLocale: Locale
  cvLanguage: Locale
  profileError: ProfileStorageCode | null
  generatedMaterials: GeneratedMaterials | null
  lastAcceptedMaterials: GeneratedMaterials | null
  typesafeKey: string
  apiKey: string
  isReviewingRepo: boolean
  isGenerating: boolean
  lastReviewSummary: string
  jobPosting: string
  applicationRevision: number
}

type Action = { type: "NEW_APPLICATION" } | {
  type: "SET_TYPESAFE_KEY"
  payload: string
} | {
  type: "SET_CV_LANGUAGE"
  payload: Locale
} | {
  type: "SET_UI_LOCALE"
  payload: Locale
} | {
  type: "SET_MATERIALS"
  payload: GeneratedMaterials
} | {
  type: "SET_API_KEY"
  payload: string
} | {
  type: "SET_REVIEWING"
  payload: boolean
} | {
  type: "SET_GENERATING"
  payload: boolean
} | {
  type: "SET_REVIEW_SUMMARY"
  payload: string
} | {
  type: "SET_JOB_POSTING"
  payload: string
}

function reducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case "NEW_APPLICATION":
      return {
        ...state,
        jobPosting: "",
        applicationRevision: state.applicationRevision + 1,
      }
    case "SET_UI_LOCALE":
      return { ...state, uiLocale: action.payload }
    case "SET_CV_LANGUAGE":
      return { ...state, cvLanguage: action.payload }
    case "SET_MATERIALS":
      return {
        ...state,
        generatedMaterials: action.payload,
        lastAcceptedMaterials:
          action.payload.acceptedResume || action.payload.acceptedArtifacts
            ? action.payload
            : state.lastAcceptedMaterials,
      }
    case "SET_TYPESAFE_KEY":
      return { ...state, typesafeKey: action.payload }
    case "SET_API_KEY":
      return { ...state, apiKey: action.payload }
    case "SET_REVIEWING":
      return { ...state, isReviewingRepo: action.payload }
    case "SET_GENERATING":
      return { ...state, isGenerating: action.payload }
    case "SET_REVIEW_SUMMARY":
      return { ...state, lastReviewSummary: action.payload }
    case "SET_JOB_POSTING":
      return { ...state, jobPosting: action.payload }
    default:
      return state
  }
}

function readSetting(key: string): string {
  try {
    return localStorage.getItem(key) || ""
  } catch {
    return ""
  }
}

function writeSetting(key: string, value: string) {
  try {
    if (value) localStorage.setItem(key, value)
    else localStorage.removeItem(key)
  } catch {
    /* Profile persistence reports its own errors. */
  }
}

function loadCvLanguage(): Locale {
  try {
    const saved = localStorage.getItem("careeros_cv_language")
    if (isLocale(saved)) return saved
    const document = JSON.parse(
      localStorage.getItem("careeros_curated_cv_v1") || "null",
    )
    const previous = document?.cvLanguage ?? document?.locale
    if (isLocale(previous)) return previous
  } catch {
    /* Use the initial site language for a new CV preference. */
  }
  return getInitialLocale()
}

const StoreContext = createContext<{
  state: AppState & { repository: ProfessionalRepository }
  dispatch: (action: Action) => Promise<boolean>
  profileDocument: ProfileDocument | null
  profileSaving: boolean
  accountId: string | null
  saveCanonicalCandidate: (
    expected: ProfileDocument,
    candidate: ProfileDocument,
  ) => Promise<boolean>
  refreshCanonicalProfile: () => Promise<boolean>
  editCanonicalProfile: (edit: ProfileEdit) => Promise<boolean>
  applyIngestionProposal: (
    snapshot: ProfileDocument,
    input: string,
    result: IngestionResult,
  ) => Promise<boolean>
  applyProfileProposal: (
    request: SectionReviewRequest,
    proposal: SectionProposal,
    edits: Record<string, string>,
    removals: string[],
  ) => Promise<boolean>
} | null>(null)

export function StoreProvider({
  children,
  account,
}: {
  children: ReactNode
  account?: AccountProfile
}) {
  const [profileDocument, setProfileDocument] =
    useState<ProfileDocument | null>(null)
  const optimisticDocument = useRef<ProfileDocument | null>(null)
  const documentRef = useRef<ProfileDocument | null>(null)
  const queue = useRef<Promise<boolean>>(Promise.resolve(true))
  const failed = useRef(false)
  const [ready, setReady] = useState(false)
  const [pendingProfileWrites, setPendingProfileWrites] = useState(0)
  const [profileError, setProfileError] = useState<ProfileStorageCode | null>(
    null,
  )
  const [state, rawDispatch] = useReducer(reducer, {
    uiLocale: getInitialLocale(),
    cvLanguage: account ? getInitialLocale() : loadCvLanguage(),
    profileError: null,
    generatedMaterials: null,
    lastAcceptedMaterials: null,
    typesafeKey: account ? "" : readSetting("careeros_typesafe_key"),
    apiKey: account ? "" : readSetting("careeros_apikey"),
    isReviewingRepo: false,
    isGenerating: false,
    lastReviewSummary: "",
    applicationRevision: 0,
    jobPosting: "",
  })

  useEffect(() => {
    let active = true
    Promise.resolve()
      .then(() => (account ? account.open() : openProfile(localStorage)))
      .then((doc) => {
        if (!active) return
        const pending = account?.recovery()
        // The current server read succeeded before any recovery draft is shown.
        // documentRef remains server authority; pending wording is unsaved.
        optimisticDocument.current = pending?.document ?? doc
        setProfileDocument(pending?.document ?? doc)
        documentRef.current = doc
        if (account?.hasRecovery()) {
          failed.current = true
          setProfileError(pending ? "uncertain" : "validation")
        }
        setReady(true)
      })
      .catch((error) => {
        if (!active) return
        if (!account) {
          // The existing browser-only mode retains its recovery behavior.
          try {
            const raw = localStorage.getItem(LEGACY_KEY)
            if (localStorage.getItem(PROFILE_KEY) === null && raw !== null) {
              const recovered = migrateProfile(
                JSON.parse(raw),
                crypto.randomUUID(),
              )
              optimisticDocument.current = recovered
              setProfileDocument(recovered)
            }
          } catch {
            /* Malformed originals are retained for download. */
          }
        }
        failed.current = true
        setProfileError(
          error instanceof ProfileStorageError ? error.code : "storage",
        )
        setReady(true)
      })
    const changed = (event: StorageEvent) => {
      if (account) return
      if (event.key !== PROFILE_KEY && event.key !== null) return
      if (
        !documentRef.current ||
        event.newValue === JSON.stringify(documentRef.current)
      )
        return
      // Keep the local draft and review input, but block stale writes until reload.
      failed.current = true
      setProfileError("stale")
    }
    window.addEventListener("storage", changed)
    return () => {
      active = false
      window.removeEventListener("storage", changed)
    }
  }, [])

  const commit = useCallback(
    async (expected: ProfileDocument, candidate: ProfileDocument) => {
      if (account)
        return account.save(
          expected,
          applyAccountRetention(expected, candidate),
        )
      await saveProfile(localStorage, expected, candidate)
      return candidate
    },
    [account],
  )

  const updateCanonical = useCallback(
    (build: (doc: ProfileDocument) => ProfileDocument) => {
      const expected = optimisticDocument.current
      if (!expected) return Promise.resolve(false)
      // Keep a second editor's draft outside the pending operation. Recovery of
      // the first Save must never replace a newer optimistic unsaved candidate.
      if (account && (failed.current || expected !== documentRef.current))
        return Promise.resolve(false)
      let candidate: ProfileDocument
      try {
        candidate = build(expected)
        if (account) candidate = applyAccountRetention(expected, candidate)
      } catch {
        setProfileError("validation")
        return Promise.resolve(false)
      }
      optimisticDocument.current = candidate
      setProfileDocument(candidate)
      setPendingProfileWrites((count) => count + 1)
      const saving = queue.current
        .then(async () => {
          if (failed.current || !documentRef.current) return false
          try {
            const saved = await commit(expected, candidate)
            documentRef.current = saved
            if (account && optimisticDocument.current === candidate) {
              optimisticDocument.current = saved
              setProfileDocument(saved)
            }
            return true
          } catch (error) {
            failed.current = true
            setProfileError(
              error instanceof ProfileStorageError ? error.code : "validation",
            )
            return false
          }
        })
        .finally(() => setPendingProfileWrites((count) => count - 1))
      queue.current = saving
      return saving
    },
    [commit, account],
  )
  const refreshCanonicalProfile = useCallback(() => {
    const refreshing = queue.current.then(async () => {
      try {
        const current = account
          ? await account.refresh()
          : await browserProfileLock(() => readProfile(localStorage))
        documentRef.current = current
        optimisticDocument.current = current
        failed.current = false
        setProfileDocument(current)
        setProfileError(null)
        return true
      } catch (error) {
        setProfileError(
          error instanceof ProfileStorageError ? error.code : "storage",
        )
        return false
      }
    })
    queue.current = refreshing
    return refreshing
  }, [account])
  const editCanonicalProfile = useCallback(
    (edit: ProfileEdit) => updateCanonical((doc) => editProfile(doc, edit)),
    [updateCanonical],
  )
  const persistProposal = useCallback(
    (build: (expected: ProfileDocument) => ProfileDocument) => {
      setPendingProfileWrites((count) => count + 1)
      const saving = queue.current
        .then(async () => {
          const expected = documentRef.current
          if (failed.current || !expected) return false
          try {
            const candidate = build(expected)
            const saved = await commit(expected, candidate)
            documentRef.current = saved
            optimisticDocument.current = saved
            setProfileDocument(saved)
            return true
          } catch (error) {
            setProfileError(
              error instanceof ProfileStorageError
                ? error.code
                : error instanceof Error && error.message === "stale"
                  ? "stale"
                  : "validation",
            )
            return false
          }
        })
        .finally(() => setPendingProfileWrites((count) => count - 1))
      queue.current = saving
      return saving
    },
    [commit],
  )
  const saveCanonicalCandidate = useCallback(
    (expected: ProfileDocument, candidate: ProfileDocument) =>
      persistProposal((doc) => {
        if (JSON.stringify(doc) !== JSON.stringify(expected))
          throw new ProfileStorageError("stale")
        return candidate
      }),
    [persistProposal],
  )
  const applyIngestionProposal = useCallback(
    (snapshot: ProfileDocument, input: string, result: IngestionResult) =>
      persistProposal((doc) =>
        applyIngestionDocument(doc, snapshot, input, result),
      ),
    [persistProposal],
  )
  const applyProfileProposal = useCallback(
    (
      request: SectionReviewRequest,
      proposal: SectionProposal,
      edits: Record<string, string>,
      removals: string[],
    ) =>
      persistProposal((doc) =>
        applySectionProposal(doc, request, proposal, edits, removals),
      ),
    [persistProposal],
  )
  const dispatch = useCallback(async (action: Action) => {
    rawDispatch(action)
    return true
  }, [])

  function downloadRecovery() {
    const data: Record<string, unknown> = {
      unsavedProfile: optimisticDocument.current
        ? profileView(optimisticDocument.current)
        : null,
      unsavedCanonicalProfile: optimisticDocument.current,
      ...(account ? { accountRecovery: account.recoveryExport() } : {}),
    }
    for (const key of account ? [] : [LEGACY_KEY, PROFILE_KEY]) {
      try {
        data[key] = localStorage.getItem(key)
      } catch {
        data[key] = null
      }
    }
    const url = URL.createObjectURL(
      new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }),
    )
    const anchor = document.createElement("a")
    anchor.href = url
    anchor.download = "careeros-profile-recovery.json"
    anchor.click()
    setTimeout(() => URL.revokeObjectURL(url), 1000)
  }

  useEffect(() => {
    if (!account) writeSetting("careeros_typesafe_key", state.typesafeKey)
  }, [state.typesafeKey])

  useEffect(() => {
    if (!account) writeSetting("careeros_apikey", state.apiKey)
  }, [state.apiKey])

  useEffect(() => {
    writeSetting("careeros_locale", state.uiLocale)
    document.documentElement.lang = state.uiLocale
  }, [state.uiLocale])

  useEffect(() => {
    writeSetting("careeros_cv_language", state.cvLanguage)
  }, [state.cvLanguage])

  const repository = useMemo(
    () => (profileDocument ? profileView(profileDocument) : emptyProfileView()),
    [profileDocument],
  )
  const accountSaveState = pendingProfileWrites > 0 ? "pending" : account?.state

  return (
    <StoreContext.Provider
      value={{
        state: { ...state, profileError, repository },
        dispatch,
        profileDocument,
        profileSaving: pendingProfileWrites > 0,
        accountId: account?.accountId ?? null,
        saveCanonicalCandidate,
        editCanonicalProfile,
        refreshCanonicalProfile,
        applyProfileProposal,
        applyIngestionProposal,
      }}
    >
      {profileError && (
        <div
          role="alert"
          className="border-b border-amber-300 bg-amber-50 px-4 py-3 text-sm text-amber-950"
        >
          <p>
            {account
              ? state.uiLocale === "pt-BR"
                ? "O Perfil ainda não foi confirmado. Suas alterações continuam disponíveis nesta sessão. Baixe a cópia antes de sair ou recarregar."
                : "Your Profile is not confirmed saved. Your edits remain available in this session. Download a copy before leaving or reloading."
              : translate(
                  state.uiLocale,
                  `profile.persistence.${profileError}`,
                )}
          </p>
          {account?.hasRecovery() && !account.checkpointStored && (
            <p>
              {state.uiLocale === "pt-BR"
                ? "O armazenamento de recuperação está indisponível. Mantenha esta aba aberta e baixe uma cópia antes de sair."
                : "Recovery storage is unavailable. Keep this tab open and download a copy before leaving."}
            </p>
          )}
          <div className="mt-2 flex gap-4">
            <button
              type="button"
              className="underline"
              onClick={downloadRecovery}
            >
              {translate(state.uiLocale, "profile.persistence.download")}
            </button>
            {account?.recovery() && (
              <button
                type="button"
                disabled={pendingProfileWrites > 0}
                className="underline"
                onClick={() => {
                  setPendingProfileWrites((count) => count + 1)
                  void account
                    .retry()
                    .then((saved) => {
                      documentRef.current = saved
                      optimisticDocument.current = saved
                      setProfileDocument(saved)
                      failed.current = false
                      setProfileError(null)
                    })
                    .catch((error) =>
                      setProfileError(
                        error instanceof ProfileStorageError
                          ? error.code
                          : "uncertain",
                      ),
                    )
                    .finally(() =>
                      setPendingProfileWrites((count) => count - 1),
                    )
                }}
              >
                {state.uiLocale === "pt-BR"
                  ? "Tentar o mesmo salvamento"
                  : "Retry the same Save"}
              </button>
            )}
            {account?.hasRecovery() && (
              <button
                type="button"
                data-discard-recovery
                disabled={pendingProfileWrites > 0}
                className="underline"
                onClick={() => {
                  if (
                    !window.confirm(
                      state.uiLocale === "pt-BR"
                        ? "Descartar a cópia de recuperação e recarregar o Perfil da conta? Isso não desfaz um salvamento no servidor."
                        : "Discard the recovery copy and reload your account Profile? This does not undo a server Save.",
                    )
                  )
                    return
                  try {
                    account.discardRecovery()
                    void refreshCanonicalProfile()
                  } catch {
                    setProfileError("storage")
                  }
                }}
              >
                {state.uiLocale === "pt-BR"
                  ? "Descartar cópia de recuperação"
                  : "Discard recovery copy"}
              </button>
            )}
            <button
              type="button"
              className="underline"
              data-profile-refresh
              onClick={() => void refreshCanonicalProfile()}
            >
              {translate(state.uiLocale, "profile.persistence.reload")}
            </button>
          </div>
        </div>
      )}
      {account && accountSaveState && (
        <p
          role="status"
          className="border-b px-4 py-2 text-sm"
          data-account-save-state={accountSaveState}
        >
          {state.uiLocale === "pt-BR"
            ? {
                idle: "Alterações exigem Salvar.",
                pending: "Salvando…",
                failed: "Não foi salvo. Alterações mantidas.",
                uncertain:
                  "Confirmação pendente. Verifique antes de tentar outra alteração.",
                confirmed: `Salvamento confirmado na revisão ${account.historicalRevision}.`,
              }[accountSaveState]
            : {
                idle: "Changes require Save.",
                pending: "Saving…",
                failed: "Save failed. Edits retained.",
                uncertain:
                  "Save outcome is uncertain. Check before making another change.",
                confirmed: `Save confirmed at revision ${account.historicalRevision}.`,
              }[accountSaveState]}
        </p>
      )}
      {ready ? (
        children
      ) : (
        <p role="status" className="p-4">
          {translate(state.uiLocale, "profile.persistence.loading")}
        </p>
      )}
    </StoreContext.Provider>
  )
}

export function useStore() {
  const ctx = useContext(StoreContext)
  if (!ctx) throw new Error("useStore must be inside StoreProvider")
  return ctx
}

export function useI18n() {
  const { state, dispatch } = useStore()
  const t = useCallback(
    (key: TranslationKey, values?: Record<string, TranslationValue>) =>
      translate(state.uiLocale, key, values),
    [state.uiLocale],
  )
  const setUiLocale = useCallback(
    (locale: Locale) => dispatch({ type: "SET_UI_LOCALE", payload: locale }),
    [dispatch],
  )

  return { uiLocale: state.uiLocale, setUiLocale, t }
}
